// QORVEX Sequence - archivo único (funciona con doble clic en Edge, sin servidor).
// Generado por tools/build.py a partir de js/*.js. No editar a mano: editar los fuentes y regenerar.

// ---- js/logos.js ----
// Logos para los PDF (embebidos para que funcionen sin servidor). Generado a partir de los archivos de marca.
const LOGOS_PDF = {"international": {"src": "data:image/png;base64,", "w": 600, "h": 131}, "sese": {"src": "data:image/png;base64,", "w": 600, "h": 156}};

// Imágenes añadidas para el formato de impresión: camión (icono de la secuencia) y marca de agua CH.
LOGOS_PDF.camion = {"src": "data:image/png;base64,", "w": 480, "h": 198};
LOGOS_PDF.marca = {"src": "data:image/png;base64,", "w": 260, "h": 235};

// ---- js/core.js ----
// QORVEX Sequence - lógica pura (sin pantalla ni archivos). Replica las macros del Excel.
// Reglas tomadas de: ExtraerPlaneadoV2, Resumir, Pivot, GenerarEsqueleto, Imprimir_EtiquetasV2.

const FAMILIA_NO_ASIGNADA = 'Kit No Asignado';
const ETIQUETAS_POR_PAGINA = 36; // 2 columnas x 18 filas, como la hoja Labels

// Quita el prefijo de línea ("2-520202" -> línea "2", valor "520202").
function splitPrefix(value) {
  const s = String(value ?? '').trim();
  const i = s.indexOf('-');
  return i >= 0 ? { prefix: s.slice(0, i).trim(), value: s.slice(i + 1).trim() } : { prefix: '', value: s };
}

// Clave de comparación de job: sin prefijo y sin ceros a la izquierda.
function normalizeJob(value) {
  const { value: v } = splitPrefix(value);
  return v.replace(/^0+(?=\d)/, '');
}

// Pegado desde Excel (TSV): columna 1 = job, columna 2 = lineset (opcional). Máximo 1000 filas.
function parsePlanPaste(text, max = 1000) {
  const errors = [];
  const lines = String(text ?? '').split(/\r?\n/).map(l => l.trim()).filter(Boolean);
  if (lines.length > max) errors.push(`Solo se toman las primeras ${max} filas (pegaste ${lines.length}).`);
  const rows = lines.slice(0, max).map((line, idx) => {
    const cols = line.split('\t');
    const job = splitPrefix(cols[0]);
    const ls = splitPrefix(cols[1] ?? '');
    return {
      n: idx + 1,
      linea: job.prefix || ls.prefix,
      job: job.value,
      jobKey: normalizeJob(job.value),
      lineset: ls.value,
    };
  });
  const sinJob = rows.filter(r => !r.jobKey).length;
  if (sinJob) errors.push(`${sinJob} fila(s) sin job; se ignorarán.`);
  return { rows: rows.filter(r => r.jobKey), errors };
}

// bdata: Map item -> { descripcion, familia, familias[] }
// Un ítem puede pertenecer a varias familias: devuelve todas. Si no existe en la base: 'Kit No Asignado'.
function familiasDeItem(item, bdata) {
  const rec = bdata.get(item);
  const lista = rec && rec.familias && rec.familias.length ? rec.familias : (rec && rec.familia ? [rec.familia] : []);
  const limpias = lista.map(f => String(f).trim()).filter(Boolean);
  return limpias.length ? [...new Set(limpias)] : [FAMILIA_NO_ASIGNADA];
}
function familyOf(item, bdata) {
  return familiasDeItem(item, bdata)[0];
}

// planRows: salida de parsePlanPaste. matches: filas leídas del TXT {item, qty, router, jobKey}.
// Devuelve Planeado (agrupado por job, en el orden del plan) y los jobs no encontrados.
function buildPlaneado(planRows, matches, bdata) {
  const orden = new Map();
  const linesetPorJob = new Map();
  planRows.forEach((r, i) => {
    if (!orden.has(r.jobKey)) { orden.set(r.jobKey, i); linesetPorJob.set(r.jobKey, r.lineset); }
  });
  const grupos = new Map();
  for (const m of matches) {
    if (!grupos.has(m.jobKey)) grupos.set(m.jobKey, []);
    grupos.get(m.jobKey).push(m);
  }
  const planeado = [];
  for (const jobKey of [...grupos.keys()].sort((a, b) => orden.get(a) - orden.get(b))) {
    for (const m of grupos.get(jobKey)) {
      for (const familia of familiasDeItem(m.item, bdata)) {
        planeado.push({
          item: m.item,
          qty: m.qty,
          router: m.router,
          job: jobKey,
          lineset: linesetPorJob.get(jobKey) ?? '',
          familia,
        });
      }
    }
  }
  const noEncontrados = [...orden.keys()].filter(k => !grupos.has(k));
  return { planeado, noEncontrados };
}

// Resumir: filas de Planeado de una familia. Descripción desde la base de ítems ("Nuevo" si no existe).
function buildResumen(planeado, familia, bdata) {
  const fam = String(familia).trim();
  return planeado
    .filter(r => String(r.familia).trim() === fam)
    .map(r => ({
      sku: r.item,
      qty: r.qty,
      router: r.router,
      job: r.job,
      rev: '',
      lineset: r.lineset,
      descripcion: bdata.get(r.item)?.descripcion || 'Nuevo',
      nameKit: fam,
    }));
}

// Pivot: suma de piezas por item (como la hoja Pivot), con total general.
function buildPivot(resumen) {
  const mapa = new Map();
  for (const r of resumen) mapa.set(r.sku, (mapa.get(r.sku) || 0) + Number(r.qty || 0));
  const filas = [...mapa.entries()].map(([item, cantidad]) => ({ item, cantidad }));
  const total = filas.reduce((a, f) => a + f.cantidad, 0);
  return { filas, total };
}

// Esqueleto: bloques de hasta `capacidad` jobs (1..20). Cada bloque = una hoja/página.
function buildEsqueletoBlocks(resumen, capacidad, linea, familia) {
  const cap = Number(capacidad);
  if (!(cap >= 1 && cap <= 20)) throw new Error('La capacidad de la facilidad debe estar entre 1 y 20.');
  const jobs = [];
  const linesetDe = new Map();
  for (const r of resumen) {
    if (!linesetDe.has(r.job)) { linesetDe.set(r.job, r.lineset); jobs.push(r.job); }
  }
  const descripcion = new Map();
  for (const r of resumen) if (!descripcion.has(r.sku)) descripcion.set(r.sku, r.descripcion);

  const bloques = [];
  const total = Math.ceil(jobs.length / cap);
  for (let b = 0; b < total; b++) {
    const jobsBloque = jobs.slice(b * cap, (b + 1) * cap);
    const enBloque = new Set(jobsBloque);
    const items = new Map(); // key router|sku -> { router, sku, cells: Map job->qty }
    for (const r of resumen) {
      if (!enBloque.has(r.job)) continue;
      const key = `${r.router}|${r.sku}`;
      if (!items.has(key)) items.set(key, { router: r.router, sku: r.sku, cells: new Map() });
      const it = items.get(key);
      it.cells.set(r.job, (it.cells.get(r.job) || 0) + Number(r.qty || 0));
    }
    const filas = [...items.values()].map(it => {
      const cantidades = jobsBloque.map(j => it.cells.get(j) ?? null);
      return {
        router: it.router,
        sku: it.sku,
        desc: descripcion.get(it.sku) || '',
        cantidades,
        subtotal: cantidades.reduce((a, c) => a + (c ?? 0), 0),
      };
    });
    const subtotales = jobsBloque.map((_, c) => filas.reduce((a, f) => a + (f.cantidades[c] ?? 0), 0));
    bloques.push({
      pagina: b + 1,
      linea,
      familia,
      jobs: jobsBloque.map(j => ({ job: j, lineset: linesetDe.get(j) ?? '' })),
      filas,
      subtotales,
      total: subtotales.reduce((a, s) => a + s, 0),
      secuencia: jobsBloque.map((_, i) => i + 1),
    });
  }
  return bloques;
}

// Etiquetas: un renglón por JOB único; consecutivo 1..consMax que vuelve a 1 (igual que Imprimir_EtiquetasV2).
function buildEtiquetas(resumen, consMax) {
  const max = Number(consMax);
  if (!(max >= 1)) throw new Error('La cantidad máxima de consecutivos debe ser mayor a 0.');
  const vistos = new Map();
  for (const r of resumen) {
    if (!vistos.has(r.job)) vistos.set(r.job, { job: r.job, lineset: r.lineset, sku: r.sku });
  }
  let cons = 1;
  return [...vistos.values()].map(j => {
    const etiqueta = { cons, lineset: j.lineset, job: j.job, sku: j.sku, texto: `Cons: ${cons} // LN: ${j.lineset} // JOB: ${j.job}` };
    cons = cons >= max ? 1 : cons + 1;
    return etiqueta;
  });
}

function paginarEtiquetas(etiquetas, porPagina = ETIQUETAS_POR_PAGINA) {
  const paginas = [];
  for (let i = 0; i < etiquetas.length; i += porPagina) paginas.push(etiquetas.slice(i, i + porPagina));
  return paginas;
}

// ---- js/store.js ----
// Lectura y escritura de archivos JSON dentro de la carpeta de trabajo (configuración, usuarios, etc.).
async function readJson(dir, name, fallback) {
  try {
    const fh = await dir.getFileHandle(name);
    return JSON.parse(await (await fh.getFile()).text());
  } catch (e) {
    if (e.name === 'NotFoundError') return fallback;
    throw e;
  }
}

async function writeJson(dir, name, obj) {
  const fh = await dir.getFileHandle(name, { create: true });
  const w = await fh.createWritable();
  await w.write(JSON.stringify(obj, null, 2));
  await w.close();
}

// Copia un archivo de texto de una carpeta a otra. Devuelve false si el origen no existe.
async function copiarArchivo(origen, nombre, destino) {
  let texto;
  try {
    texto = await (await (await origen.getFileHandle(nombre)).getFile()).text();
  } catch (e) {
    if (e.name === 'NotFoundError') return false;
    throw e;
  }
  const w = await (await destino.getFileHandle(nombre, { create: true })).createWritable();
  await w.write(texto);
  await w.close();
  return true;
}

// Respaldo: crea respaldos/AAAA-MM-DD_HHMMSS con usuarios, configuración y registro de auditoría.
const ARCHIVOS_RESPALDO = ['usuarios.json', 'configuracion.json', 'registro_auditoria.jsonl'];
async function respaldar(root, respaldoDir) {
  const d = new Date(), p = n => String(n).padStart(2, '0');
  const carpeta = `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}_${p(d.getHours())}${p(d.getMinutes())}${p(d.getSeconds())}`;
  const dir = await respaldoDir.getDirectoryHandle(carpeta, { create: true });
  const archivos = [];
  for (const nombre of ARCHIVOS_RESPALDO) {
    if (await copiarArchivo(root, nombre, dir)) archivos.push(nombre);
  }
  return { carpeta, archivos };
}

// ---- js/base.js ----
// Base de ítems: lee "Base de ítems.xlsm" de la carpeta de trabajo (hoja BData: A=ítem, B=descripción, C=familia).
const NOMBRE_BASE = 'Base de ítems.xlsm';

async function leerBaseItems(root) {
  let fh;
  try { fh = await root.getFileHandle(NOMBRE_BASE); }
  catch (e) { if (e.name === 'NotFoundError') return null; throw e; }
  const buf = await (await fh.getFile()).arrayBuffer();
  const wb = XLSX.read(buf, { type: 'array' });
  const hoja = wb.SheetNames.includes('BData') ? 'BData' : wb.SheetNames[0];
  const filas = XLSX.utils.sheet_to_json(wb.Sheets[hoja], { header: 1, defval: '' });
  const mapa = new Map();
  for (const r of filas) {
    const item = String(r[0] ?? '').trim();
    if (!item) continue;
    if (/^(partno|item|sku|n[uú]m)/i.test(item)) continue; // encabezado
    const desc = String(r[1] ?? '').trim();
    const fam = String(r[2] ?? '').trim().replace(/\s+/g, ' ');
    if (!mapa.has(item)) mapa.set(item, { descripcion: desc, familia: fam, familias: fam ? [fam] : [] });
    else {
      const rec = mapa.get(item); // mismo ítem en otra fila de la base: se suma su familia
      if (fam && !rec.familias.includes(fam)) rec.familias.push(fam);
      if (!rec.familia) rec.familia = fam;
    }
  }
  return { mapa, hoja, total: mapa.size };
}

function familiasDe(mapa) {
  const cuenta = new Map();
  for (const rec of mapa.values()) {
    for (const f of rec.familias) cuenta.set(f, (cuenta.get(f) || 0) + 1);
  }
  return [...cuenta.entries()].sort((a, b) => a[0].localeCompare(b[0]));
}

// ---- js/outputs.js ----
// Salidas en PDF, tamaño carta (letter). Formato igual a las hojas del Excel:
// esqueletos en horizontal con JOBS y LINESET verticales; pivot con barra de título; firmas al pie.
// Requiere jsPDF y jspdf-autotable cargados en index.html.
// Logos: js/logos.js (LOGOS_PDF).

const SLOTS = 20;              // columnas de jobs fijas, como la hoja del Excel (01..20)
const AZUL = [0, 96, 224];
const OSCURO = [64, 64, 64];
const BLANCO = [255, 255, 255];
const NEGRO = [0, 0, 0];

function nuevoDoc(orientacion) {
  const { jsPDF } = window.jspdf;
  return new jsPDF({ orientation: orientacion, unit: 'pt', format: 'letter' });
}

function fechaLarga(d) {
  const p = n => String(n).padStart(2, '0');
  return `${p(d.getDate())}/${p(d.getMonth() + 1)}/${d.getFullYear()} ${p(d.getHours())}:${p(d.getMinutes())} ${d.getHours() >= 12 ? 'p. m.' : 'a. m.'}`;
}
const MES_ESC = d => d.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });

// Encabezado: logo SESÉ a la izquierda, título centrado, logo INTERNATIONAL a la derecha.
function logoEnAltura(doc, logo, x, y, alto, alinear) {
  const ancho = alto * logo.w / logo.h;
  doc.addImage(logo.src, 'PNG', alinear === 'right' ? x - ancho : x, y, ancho, alto);
}
function encabezado(doc, W, titulo) {
  logoEnAltura(doc, LOGOS_PDF.sese, 28, 16, 30, 'left');
  doc.setTextColor(...NEGRO); doc.setFont('helvetica', 'bold'); doc.setFontSize(10);
  doc.text(titulo, W / 2, 30, { align: 'center' });
  logoEnAltura(doc, LOGOS_PDF.international, W - 28, 14, 26, 'right');
}

// Marca de agua CH: casi imperceptible, centrada en la parte de abajo de la hoja.
function marcaAgua(doc, W, H) {
  const alto = 90, ancho = alto * LOGOS_PDF.marca.w / LOGOS_PDF.marca.h;
  doc.saveGraphicsState();
  doc.setGState(new doc.GState({ opacity: 0.06 }));
  doc.addImage(LOGOS_PDF.marca.src, 'PNG', W / 2 - ancho / 2, H - 150, ancho, alto);
  doc.restoreGraphicsState();
}

// Texto del formato del pie: plantilla (con {mes}) + folio asignado por la empresa.
function textoFormato(formato, impreso) {
  const f = formato || {};
  const base = String(f.texto ?? '{mes} ESC').replace(/\{mes\}/g, MES_ESC(impreso));
  const folio = String(f.folio || '').trim();
  return folio ? `${base} ${folio}` : base;
}

// Pie: firmas y fecha de impresión (igual al Excel).
function pie(doc, W, H, impreso, pagina, paginas, formato) {
  const y = H - 46;
  doc.setTextColor(...NEGRO); doc.setFont('helvetica', 'normal'); doc.setFontSize(7.5);
  doc.setDrawColor(...NEGRO); doc.setLineWidth(0.5);
  doc.line(28, y - 14, 210, y - 14);
  doc.text('Fecha y Firma Armado de Secuencia', 28, y - 3);
  doc.text(textoFormato(formato, impreso), 28, y + 8);
  doc.text(`Página ${pagina} de ${paginas}`, W / 2, y + 2, { align: 'center' });
  doc.line(W - 28 - 210, y - 14, W - 28, y - 14);
  doc.text('Fecha y Firma Transferido a Línea', W - 28, y - 3, { align: 'right' });
  doc.text('Printed on: ' + fechaLarga(impreso), W - 28, y + 8, { align: 'right' });
}

// Celda rectangular con texto centrado (o rotado 90° para JOBS / LINESET / números de job).
function celda(doc, x, y, w, h, texto, { fondo = null, color = NEGRO, negrita = false, tam = 8, rotar = false, alinear = 'center' } = {}) {
  doc.setDrawColor(...NEGRO); doc.setLineWidth(0.4);
  if (fondo) { doc.setFillColor(...fondo); doc.rect(x, y, w, h, 'FD'); } else doc.rect(x, y, w, h, 'S');
  if (texto === '' || texto == null) return;
  doc.setTextColor(...color); doc.setFont('helvetica', negrita ? 'bold' : 'normal'); doc.setFontSize(tam);
  const t = String(texto);
  if (rotar) {
    doc.text(t, x + w / 2 + tam / 3, y + h - 4, { angle: 90 });
  } else {
    const ax = alinear === 'left' ? x + 3 : alinear === 'right' ? x + w - 3 : x + w / 2;
    const ay = y + h / 2 + tam / 3;
    doc.text(t, ax, ay, { align: alinear });
  }
}

// Esqueletos: una o más hojas por bloque (si la tabla no cabe, continúa en otra hoja).
// Filas de router por hoja de esqueletos (constante del diseño).
const FILAS_ESQ = Math.floor((612 - 62 - 72 - 14 - 60 - 60 - 2 * 13) / 13);

// Parte cada bloque en hojas (si el bloque no cabe, continúa en otra hoja).
function partirEnHojas(bloques) {
  const hojas = [];
  bloques.forEach(b => {
    const trozos = [];
    for (let i = 0; i < Math.max(b.filas.length, 1); i += FILAS_ESQ) trozos.push(b.filas.slice(i, i + FILAS_ESQ));
    trozos.forEach((filas, t) => hojas.push({ b, filas, parte: t + 1, partes: trozos.length }));
  });
  if (!hojas.length) hojas.push({ b: { pagina: 1, jobs: [], filas: [], subtotales: [], total: 0, secuencia: [] }, filas: [], parte: 1, partes: 1 });
  return hojas;
}

// Esqueletos. Si se pasa un documento, las hojas se agregan al final de ese documento (libro único).
function pdfEsqueletos(bloques, { familia, linea, impreso = new Date(), formato = null, offset = 0, totalPaginas = 0 } = {}, doc = nuevoDoc('landscape')) {
  const W = 792, H = 612;
  const C = { router: 66, sku: 78, dsc: 148, jobs: 14, slot: 20, total: 30 };  // slot 20 pt; dsc llena el ancho carta
  const ALTO_JOBS = 60, ALTO_LINESET = 60, ALTO_FILA = 13, Y_TABLA = 72;
  const hojas = partirEnHojas(bloques);
  const total = totalPaginas || hojas.length;

  hojas.forEach((h, n) => {
    if (n > 0) doc.addPage('letter', 'landscape');
    const { b } = h;
    marcaAgua(doc, W, H);
    encabezado(doc, W, 'ESQUELETOS PARA SECUENCIA');
    const x0 = 28;
    const xSlot = x0 + C.router + C.sku + C.dsc + C.jobs;
    const xTotal = xSlot + SLOTS * C.slot;
    const yR0 = Y_TABLA, yJobs = yR0 + 14, yLs = yJobs + ALTO_JOBS;
    const yCuerpo = yLs + ALTO_LINESET;

    // Fila de números de columna (01..20) y encabezado "Página n / Secuencia"
    celda(doc, x0, yR0, C.router, 14, 'Secuencia', { negrita: true, tam: 8, alinear: 'left' });
    celda(doc, x0 + C.router, yR0, C.sku + C.dsc, 14, String(familia), { negrita: true, tam: 8 });
    celda(doc, x0 + C.router + C.sku + C.dsc, yR0, C.jobs, 14, '');
    for (let s = 0; s < SLOTS; s++) celda(doc, xSlot + s * C.slot, yR0, C.slot, 14, String(s + 1).padStart(2, '0'), { tam: 9, negrita: true });
    celda(doc, xTotal, yR0, C.total, 14, '');
    doc.setTextColor(...NEGRO); doc.setFont('symbol', 'normal'); doc.setFontSize(9);
    doc.text('S', xTotal + C.total / 2, yR0 + 10, { align: 'center' });   // Σ (fuente Symbol)

    // Fila de jobs (rotados)
    celda(doc, x0, yJobs, C.router + C.sku + C.dsc, ALTO_JOBS, '', {});
    doc.setTextColor(...NEGRO); doc.setFont('helvetica', 'bold'); doc.setFontSize(10);
    doc.text(`Línea ${linea}`, x0 + 6, yJobs + 16);
    doc.setFontSize(9);
    // Icono de camión (trailer) centrado en el espacio sku + dsc
    const anchoCamion = 120, altoCamion = anchoCamion * LOGOS_PDF.camion.h / LOGOS_PDF.camion.w;
    doc.addImage(LOGOS_PDF.camion.src, 'PNG', x0 + C.router + (C.sku + C.dsc - anchoCamion) / 2, yJobs + (ALTO_JOBS - altoCamion) / 2, anchoCamion, altoCamion);
    celda(doc, x0 + C.router + C.sku + C.dsc, yJobs, C.jobs, ALTO_JOBS, 'JOBS', { fondo: OSCURO, color: BLANCO, negrita: true, tam: 7, rotar: true });
    for (let s = 0; s < SLOTS; s++) {
      const j = b.jobs[s];
      celda(doc, xSlot + s * C.slot, yJobs, C.slot, ALTO_JOBS, j ? j.job : '', { tam: 9, rotar: true });
    }
    celda(doc, xTotal, yJobs, C.total, ALTO_JOBS, 'JOBS', { fondo: OSCURO, color: BLANCO, negrita: true, tam: 7, rotar: true });

    // Fila de LINESET (rotados) y encabezados de la tabla
    celda(doc, x0, yLs, C.router, ALTO_LINESET, 'Router', { fondo: OSCURO, color: BLANCO, negrita: true, tam: 8, alinear: 'left' });
    celda(doc, x0 + C.router, yLs, C.sku, ALTO_LINESET, 'Sku', { fondo: OSCURO, color: BLANCO, negrita: true, tam: 8, alinear: 'left' });
    celda(doc, x0 + C.router + C.sku, yLs, C.dsc, ALTO_LINESET, 'Dsc.', { fondo: OSCURO, color: BLANCO, negrita: true, tam: 8, alinear: 'left' });
    celda(doc, x0 + C.router + C.sku + C.dsc, yLs, C.jobs, ALTO_LINESET, 'LINESET', { fondo: OSCURO, color: BLANCO, negrita: true, tam: 7, rotar: true });
    for (let s = 0; s < SLOTS; s++) {
      const j = b.jobs[s];
      celda(doc, xSlot + s * C.slot, yLs, C.slot, ALTO_LINESET, j ? j.lineset : '', { tam: 9, rotar: true });
    }
    celda(doc, xTotal, yLs, C.total, ALTO_LINESET, 'LINESET', { fondo: OSCURO, color: BLANCO, negrita: true, tam: 7, rotar: true });

    // Cuerpo: un renglón por router + sku
    let y = yCuerpo;
    h.filas.forEach(f => {
      celda(doc, x0, y, C.router, ALTO_FILA, f.router, { alinear: 'left', tam: 7 });
      celda(doc, x0 + C.router, y, C.sku, ALTO_FILA, f.sku, { alinear: 'left', tam: 7 });
      celda(doc, x0 + C.router + C.sku, y, C.dsc, ALTO_FILA, f.desc, { alinear: 'left', tam: 6 });
      celda(doc, x0 + C.router + C.sku + C.dsc, y, C.jobs, ALTO_FILA, '');
      for (let s = 0; s < SLOTS; s++) {
        const c = f.cantidades[s];
        celda(doc, xSlot + s * C.slot, y, C.slot, ALTO_FILA, c == null ? '' : c, { tam: 9 });
      }
      celda(doc, xTotal, y, C.total, ALTO_FILA, f.subtotal, { negrita: true, tam: 7 });
      y += ALTO_FILA;
    });

    // Caja "Página n | total" al pie (ocupa subtotal y secuencia en la última hoja del bloque)
    const altoCaja = h.parte === h.partes ? 2 * ALTO_FILA : ALTO_FILA;
    celda(doc, x0, y, C.router, altoCaja, `Página ${b.pagina} | ${bloques.length}`, { fondo: [191, 191, 191], negrita: true, tam: 7 });

    // Subtotal y secuencia (en la última hoja de cada bloque)
    if (h.parte === h.partes) {
      celda(doc, x0 + C.router, y, C.sku + C.dsc + C.jobs, ALTO_FILA, 'Subtotal', { fondo: OSCURO, color: BLANCO, negrita: true, tam: 7, alinear: 'right' });
      for (let s = 0; s < SLOTS; s++) {
        const v = b.subtotales[s];
        celda(doc, xSlot + s * C.slot, y, C.slot, ALTO_FILA, v == null ? '' : v, { fondo: OSCURO, color: BLANCO, negrita: true, tam: 9 });
      }
      celda(doc, xTotal, y, C.total, ALTO_FILA, b.total, { fondo: OSCURO, color: BLANCO, negrita: true, tam: 7 });
      y += ALTO_FILA;
      celda(doc, x0 + C.router, y, C.sku + C.dsc + C.jobs, ALTO_FILA, 'Secuencia', { fondo: OSCURO, color: BLANCO, negrita: true, tam: 7, alinear: 'right' });
      for (let s = 0; s < SLOTS; s++) {
        const v = b.secuencia[s];
        celda(doc, xSlot + s * C.slot, y, C.slot, ALTO_FILA, v == null ? '' : v, { fondo: OSCURO, color: BLANCO, negrita: true, tam: 9 });
      }
      celda(doc, xTotal, y, C.total, ALTO_FILA, '', { fondo: OSCURO });
    }

    pie(doc, W, H, impreso, offset + n + 1, total, formato);
  });
  return doc;
}

// Pivot: sumarización por ítem de la familia (sin total, como la hoja Pivot del Excel).
// Pivot. Si se pasa un documento, la hoja se agrega al final de ese documento (libro único).
function pdfPivot(pivot, { familia, linea, impreso = new Date(), formato = null, offset = 0, totalPaginas = 1 } = {}, doc = null) {
  if (doc) doc.addPage('letter', 'portrait'); else doc = nuevoDoc('portrait');
  const W = 612, H = 792;
  marcaAgua(doc, W, H);
  encabezado(doc, W, 'Sumarización');
  const x = 150, anchoItem = 170, anchoCant = 90, y0 = 80;
  doc.setFillColor(38, 38, 38);
  doc.rect(x, y0, anchoItem + anchoCant, 22, 'F');
  doc.setTextColor(...BLANCO); doc.setFont('helvetica', 'normal'); doc.setFontSize(11);
  doc.text(String(familia), x + 6, y0 + 15);
  doc.text(`Línea ${linea}`, x + anchoItem + anchoCant - 6, y0 + 15, { align: 'right' });

  const body = pivot.filas.map(f => [f.item, String(f.cantidad)]);
  doc.autoTable({
    head: [['Item', 'Cantidad']],
    body,
    startY: y0 + 22,
    theme: 'plain',
    tableWidth: anchoItem + anchoCant,
    margin: { left: x, right: W - x - anchoItem - anchoCant },
    styles: { fontSize: 9, cellPadding: 3, textColor: NEGRO },
    headStyles: { fillColor: [38, 38, 38], textColor: BLANCO, fontStyle: 'normal' },
    columnStyles: { 0: { cellWidth: anchoItem }, 1: { cellWidth: anchoCant, halign: 'right' } },
    didParseCell: d => {
      if (d.section === 'body') d.cell.styles.lineWidth = 0;
    },
  });
  pie(doc, W, H, impreso, offset + 1, totalPaginas, formato);
  return doc;
}

// Libro único: esqueletos y pivot en el mismo PDF (y en el mismo trabajo de impresión).
function pdfLibro(bloques, pivot, opts = {}) {
  const doc = nuevoDoc('landscape');
  const hojas = partirEnHojas(bloques);
  const totalPaginas = hojas.length + 1;
  pdfEsqueletos(bloques, { ...opts, totalPaginas }, doc);
  pdfPivot(pivot, { ...opts, offset: hojas.length, totalPaginas }, doc);
  return doc;
}

// Etiquetas: 36 por hoja carta (2 columnas x 18 renglones), llenado por columna como la hoja Labels.
function pdfEtiquetas(paginas) {
  const doc = nuevoDoc('portrait');
  const M = 30, COLS = 2, RENGLONES = 18;
  const W = (612 - 2 * M) / COLS, H = (792 - 2 * M) / RENGLONES;
  paginas.forEach((pagina, p) => {
    if (p > 0) doc.addPage('letter', 'portrait');
    pagina.forEach((et, i) => {
      const col = Math.floor(i / RENGLONES), ren = i % RENGLONES;
      const x = M + col * W, y = M + ren * H;
      doc.setDrawColor(150); doc.rect(x, y, W, H);
      doc.setFont('helvetica', 'bold'); doc.setFontSize(9);
      doc.text(et.texto, x + 6, y + H / 2 + 3);
    });
  });
  return doc;
}

// Guarda el PDF en impresiones/<usuario>/<familia>/<AAAA-MM-DD_HHMM>/<nombre>
function seguro(texto) { return String(texto).trim().replace(/[\\/:*?"<>|]/g, '_'); }
function marcaTiempo(d = new Date()) {
  const p = n => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}_${p(d.getHours())}${p(d.getMinutes())}`;
}
// impDir: carpeta base de impresiones (por defecto impresiones dentro de la carpeta de trabajo).
async function guardarPdf(impDir, usuario, familia, nombre, doc) {
  const dirUsuario = await impDir.getDirectoryHandle(usuario, { create: true });
  const dirFamilia = await dirUsuario.getDirectoryHandle(seguro(familia), { create: true });
  const dirCorrida = await dirFamilia.getDirectoryHandle(marcaTiempo(), { create: true });
  const fh = await dirCorrida.getFileHandle(nombre, { create: true });
  const w = await fh.createWritable();
  await w.write(doc.output('blob'));
  await w.close();
  return `${impDir.name}/${usuario}/${seguro(familia)}/${marcaTiempo()}/${nombre}`;
}

// Abre el diálogo de impresión del navegador con el PDF listo (eliges la impresora y confirmas).
// Si el navegador no permite imprimir desde el marco, abre el PDF en una pestaña para imprimirlo desde ahí.
function imprimirEnDialogo(doc) {
  const url = doc.output('bloburl');
  const marco = document.createElement('iframe');
  marco.style.cssText = 'position:fixed;right:0;bottom:0;width:1px;height:1px;border:0;opacity:0;';
  marco.src = url;
  document.body.appendChild(marco);
  marco.onload = () => {
    setTimeout(() => {
      try { marco.contentWindow.focus(); marco.contentWindow.print(); }
      catch (e) { window.open(url, '_blank'); }
    }, 400);
  };
  setTimeout(() => marco.remove(), 120000);
}

// ---- js/txt-source.js ----
// QORVEX Sequence - lectura e índice del TXT de planeación.
// Formato por fila: item@piezas@router@job   (job puede venir vacío)
// Funciona en el navegador (File.stream()) y en Node (fs.createReadStream),
// porque sólo usa un iterable asíncrono de fragmentos (Uint8Array).

function parseLine(line) {
  const p = line.replace(/\r$/, '').split('@');
  if (p.length < 4) return null;           // línea inválida o vacía
  const [item, piezas, router, job] = p;
  if (!item || !router) return null;
  const qty = Number(piezas);
  return {
    item: item.trim(),
    qty: Number.isFinite(qty) ? qty : 0,
    router: router.trim(),
    job: job.trim(),                        // puede ser '' (job vacío)
  };
}

// Convierte un iterable asíncrono de fragmentos en líneas.
async function* linesFromChunks(chunks) {
  const decoder = new TextDecoder('utf-8');
  let carry = '';
  for await (const chunk of chunks) {
    carry += decoder.decode(chunk, { stream: true });
    let idx;
    while ((idx = carry.indexOf('\n')) !== -1) {
      yield carry.slice(0, idx);
      carry = carry.slice(idx + 1);
    }
  }
  carry += decoder.decode();
  if (carry.length) yield carry;
}

// Recorre un TXT y entrega sólo las filas de los routers/jobs seleccionados.
// selection: { routers: Set<string>, jobs?: Set<string> }  (jobs normalizados)
// Si no hay jobs, se traen todas las filas de esos routers.
async function scanTxt(chunks, selection, sourceName, onMatch) {
  const stats = { total: 0, matched: 0, emptyJob: 0, invalid: 0 };
  for await (const line of linesFromChunks(chunks)) {
    if (!line.trim()) continue;
    stats.total++;
    const row = parseLine(line);
    if (!row) { stats.invalid++; continue; }
    if (!row.job) stats.emptyJob++;
    if (!selection.routers.has(row.router)) continue;
    const jobKey = normalizeJob(row.job);
    if (selection.jobs && !selection.jobs.has(jobKey)) continue;
    stats.matched++;
    onMatch({ ...row, jobKey, source: sourceName });
  }
  return stats;
}

// Búsqueda de jobs que no aparecen en el primer TXT, en todos los TXT de la carpeta.
// files: [{ name, open: () => AsyncIterable<Uint8Array> }] en orden de preferencia.
async function findJobsAcrossFiles(files, selection, onMatch) {
  const found = new Set();
  for (const f of files) {
    const pending = { routers: selection.routers, jobs: new Set([...selection.jobs].filter(j => !found.has(j))) };
    if (pending.jobs.size === 0) break;
    await scanTxt(f.open(), pending, f.name, row => {
      found.add(row.jobKey);
      onMatch(row);
    });
  }
  const missing = [...selection.jobs].filter(j => !found.has(j));
  return { found, missing };
}

// ---- js/audit.js ----
// Registro de auditoría: cada acción queda en registro_auditoria.jsonl de la carpeta de trabajo.
async function logAction(dirHandle, user, action, detail = {}) {
  const line = JSON.stringify({ ts: new Date().toISOString(), user, action, ...detail }) + '\n';
  const fh = await dirHandle.getFileHandle('registro_auditoria.jsonl', { create: true });
  const w = await fh.createWritable({ keepExistingData: true });
  const file = await fh.getFile();
  await w.seek(file.size);
  await w.write(line);
  await w.close();
}

// ---- js/auth.js ----
// Usuarios locales de la carpeta de trabajo (estilo QORVEX MOVIL).
// Archivo: usuarios.json en la carpeta de trabajo. Contraseñas guardadas como
// PBKDF2-SHA256 con sal aleatoria; nunca en texto plano ni en el repositorio.
// Sirve para saber quién hizo cada cambio (registro de auditoría); no es un control de acceso fuerte.

const ITER = 210000;
const enc = new TextEncoder();

function toHex(buf) { return [...new Uint8Array(buf)].map(b => b.toString(16).padStart(2, '0')).join(''); }
function fromHex(hex) { return Uint8Array.from(hex.match(/../g).map(h => parseInt(h, 16))); }

async function hashPassword(password, saltHex) {
  const salt = saltHex ? fromHex(saltHex) : crypto.getRandomValues(new Uint8Array(16));
  const key = await crypto.subtle.importKey('raw', enc.encode(password), 'PBKDF2', false, ['deriveBits']);
  const bits = await crypto.subtle.deriveBits({ name: 'PBKDF2', salt, iterations: ITER, hash: 'SHA-256' }, key, 256);
  return { salt: toHex(salt), hash: toHex(bits), iterations: ITER };
}

async function verifyPassword(password, record) {
  const { hash } = await hashPassword(password, record.salt);
  return hash === record.hash;
}

async function readUsers(dirHandle) {
  try {
    const fh = await dirHandle.getFileHandle('usuarios.json');
    const data = JSON.parse(await (await fh.getFile()).text());
    return data.users || [];
  } catch (e) {
    if (e.name === 'NotFoundError') return [];
    throw e;
  }
}

async function writeUsers(dirHandle, users) {
  const fh = await dirHandle.getFileHandle('usuarios.json', { create: true });
  const w = await fh.createWritable();
  await w.write(JSON.stringify({ users }, null, 2));
  await w.close();
}

// El primer usuario siempre es administrador; si un registro antiguo no tiene rol, el primero es admin.
function rolDe(users, rec) {
  if (rec.rol) return rec.rol;
  return users[0] === rec ? 'admin' : 'operador';
}

// Devuelve { mode: 'create' | 'login', users } para saber qué pantalla mostrar.
async function accountMode(dirHandle) {
  const users = await readUsers(dirHandle);
  return { mode: users.length === 0 ? 'create' : 'login', users };
}

// Lista para la pantalla de Configuración (sin contraseñas).
async function listUsers(dirHandle) {
  const users = await readUsers(dirHandle);
  return users.map(u => ({ name: u.name, nombre: u.nombre || u.name, rol: rolDe(users, u), created: u.created || '' }));
}

async function createUser(dirHandle, username, password, nombre, rol = 'operador') {
  const name = username.trim();
  if (!name) throw new Error('Escribe el No. de empleado.');
  if (password.length < 4) throw new Error('La contraseña debe tener al menos 4 caracteres.');
  const users = await readUsers(dirHandle);
  if (users.some(u => u.name.toLowerCase() === name.toLowerCase())) throw new Error('Ese usuario ya existe.');
  const rolFinal = users.length === 0 ? 'admin' : (rol === 'admin' ? 'admin' : 'operador');
  const rec = await hashPassword(password);
  users.push({ name, nombre: (nombre || name).trim(), rol: rolFinal, ...rec, created: new Date().toISOString() });
  await writeUsers(dirHandle, users);
  return { name, nombre: (nombre || name).trim(), rol: rolFinal };
}

async function resetPassword(dirHandle, username, password) {
  if (password.length < 4) throw new Error('La contraseña debe tener al menos 4 caracteres.');
  const users = await readUsers(dirHandle);
  const rec = users.find(u => u.name.toLowerCase() === username.trim().toLowerCase());
  if (!rec) throw new Error('Ese No. de empleado no existe.');
  Object.assign(rec, await hashPassword(password));
  await writeUsers(dirHandle, users);
  return rec.name;
}

async function login(dirHandle, username, password) {
  const users = await readUsers(dirHandle);
  const rec = users.find(u => u.name.toLowerCase() === username.trim().toLowerCase());
  if (!rec) throw new Error('Usuario no encontrado. Revisa el número o pide al administrador que te dé de alta.');
  if (!(await verifyPassword(password, rec))) throw new Error('Contraseña incorrecta.');
  return { name: rec.name, nombre: rec.nombre || rec.name, rol: rolDe(users, rec) };
}

